  `date_inserted` datetime DEFAULT NULL,
  `date_step01` datetime DEFAULT NULL,
  `date_step02` datetime DEFAULT NULL,
  `date_step03` datetime DEFAULT NULL,
  `count_mailinvite_sended` int DEFAULT '0',
