  `cert_apprecitation_send_count` int DEFAULT '0',
  `cert_apprecitation_send_lstdate` datetime DEFAULT NULL,
  `cert_apprecitation_print_count` int DEFAULT '0',
  `cert_apprecitation_print_lstdate` datetime DEFAULT NULL,
  PRIMARY KEY (`judge_id`),
