DROP TABLE IF EXISTS `project`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `project` (
  `project_id` int NOT NULL AUTO_INCREMENT,
  `mobarat_year` int NOT NULL,
  `school_id` int NOT NULL,
  `project_name` varchar(250) NOT NULL,
  `project_type` varchar(2) NOT NULL,
  `project_stage` varchar(2) NOT NULL,
  `project_path` varchar(2) DEFAULT NULL,
  `project_prize` varchar(2) DEFAULT NULL,
  `project_description` text,
  `project_goal` text,
  `project_tools` varchar(5000) DEFAULT NULL,
  `project_steps` text,
  `project_attachment` varchar(50) DEFAULT NULL,
  `project_oldid` int DEFAULT NULL,
  `project_name_en` varchar(250) DEFAULT NULL,
  `total_grade` double DEFAULT NULL,
  `total_grade_coef` double DEFAULT '0',
  `total_judge` int DEFAULT '0',
  `total_judgekernel` int DEFAULT '0',
  `date_inserted` datetime DEFAULT NULL,
  `date_lastupdate` datetime DEFAULT NULL,
  `date_grade_lastupdate` datetime DEFAULT NULL,
  `cert_participate_send_count` int DEFAULT '0',
  `cert_participate_send_lstdate` datetime DEFAULT NULL,
  `cert_participate_print_count` int DEFAULT '0',
  `cert_participate_print_lstdate` datetime DEFAULT NULL,
  `cert_trophy_send_count` int DEFAULT '0',
  `cert_trophy_send_lstdate` datetime DEFAULT NULL,
  `cert_trophy_print_count` int DEFAULT '0',
  `cert_trophy_print_lstdate` datetime DEFAULT NULL,
  PRIMARY KEY (`project_id`),
  KEY `mobarat_year` (`mobarat_year`),
  KEY `school_id` (`school_id`),
  CONSTRAINT `project_ibfk_1` FOREIGN KEY (`mobarat_year`) REFERENCES `mobarat` (`mobarat_year`),
  CONSTRAINT `project_ibfk_2` FOREIGN KEY (`school_id`) REFERENCES `school` (`school_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11572 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

