--
-- Table structure for table `student_scholarship`
--

DROP TABLE IF EXISTS `student_scholarship`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_scholarship` (
  `student_scholarship_id` int NOT NULL AUTO_INCREMENT,
  `student_id` int DEFAULT NULL,
  `person_id` int DEFAULT NULL,
  `mobarat_year` int DEFAULT NULL,
  `giveup` tinyint DEFAULT '0',
  `giveup_why` varchar(200) DEFAULT NULL,
  `id_attachment` varchar(45) DEFAULT NULL,
  `phone_house` varchar(45) DEFAULT NULL,
  `phone_guardian` varchar(45) DEFAULT NULL,
  `nomination_number` varchar(15) DEFAULT NULL,
  `Grade_attachment` varchar(45) DEFAULT NULL,
  `university` varchar(2) DEFAULT NULL,
  `agree_lot` int DEFAULT '0',
  `Major` varchar(45) DEFAULT NULL,
  `notes` varchar(200) DEFAULT NULL,
  `assue_information` int DEFAULT '0',
  `student_class` varchar(4) DEFAULT NULL,
  PRIMARY KEY (`student_scholarship_id`),
  KEY `fk_student_id_idx` (`student_id`),
  KEY `fk_person_id_idx` (`person_id`),
  KEY `fk_mobarat_year_idx` (`mobarat_year`),
  CONSTRAINT `fk_mobarat_year` FOREIGN KEY (`mobarat_year`) REFERENCES `mobarat` (`mobarat_year`),
  CONSTRAINT `fk_person_id` FOREIGN KEY (`person_id`) REFERENCES `person` (`Person_id`),
  CONSTRAINT `fk_student_id` FOREIGN KEY (`student_id`) REFERENCES `person_student` (`Student_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1515 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

