/*!50003 DROP PROCEDURE IF EXISTS `RegisterJudgeProject` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_unicode_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE PROCEDURE `RegisterJudgeProject`(persID int(11),myear int(11))
BEGIN
	declare ptype varchar(2);
    declare tenable int;
    declare tKernel int;
    declare judeid int;
    declare pcount int;
    declare jpcount int;
    declare jstage varchar(2);
    declare lim int;
    declare judgeDayEnable int;
    declare judgeDayEnable_code_no int;
    declare judgeDayEnable_code_no_var varchar(2);
	DECLARE done INT DEFAULT 0;
    DECLARE cur CURSOR FOR 
	select judge_id,project_type,type_enable,type_kernel,judge_stage  from judge_type 
		where person_id=persID and mobarat_year=myear and (type_enable=1 or type_kernel=1);
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
	set judgeDayEnable=(select enablejudgeday from mobarat where mobarat_year=myear);
    if judgeDayEnable=1 then
		set judgeDayEnable_code_no_var=(select enablejudgedaycode_no from mobarat where mobarat_year=myear);
			if not judgeDayEnable_code_no_var is null then
				#if not(select judge_stage from person_judge where judge_id=judeid) is null then
					#if not exists(select * from judge_selecting where person_id=persID and mobarat_year=myear and select_no like concat(judgeDayEnable_code_no_var,'%') and isProjectRegister=1 ) then
                   # if not exists(select * from judge_selecting where person_id=persID and mobarat_year=myear and select_no like concat(judgeDayEnable_code_no_var,'%')  ) then
						set judgeDayEnable_code_no=judgeDayEnable_code_no_var;
						set jpcount=(select judgeprojectcount from mobarat where mobarat_year=myear);
						if jpcount is null then
							set jpcount=10;
						end if;
						OPEN cur;
						read_loop: LOOP 
						FETCH cur INTO judeid,ptype,tenable,tKernel,jstage;
							IF done THEN
								LEAVE read_loop;
							END IF;
							set pcount=(select count(project_judge.project_id) from project_judge 
											inner join project on project.project_id=project_judge.project_id
											inner join mobarat_school on mobarat_school.school_id=project.school_id and mobarat_school.mobarat_year=project.mobarat_year 
											where mobarat_school.is_present=1 and project_judge.mobarat_year=myear and judge_personId=persID
											and project_type=ptype and suite like concat(judgeDayEnable_code_no,'%'));
							if tenable=1 then
								set lim=jpcount-pcount;
							end if;
							if tKernel=1 then
								set lim=10000;
							end if;
							insert into project_judge(project_id,judge_id,judge_personId,mobarat_year)
							select project_id, judeid, persID, myear  from(
								select project_id,ct,@lim:=@lim+1 as counter
								from (
								select project_id,(select count(*) from project_judge where project.project_id=project_judge.project_id and (judgeislogin=1 or rated=1)) as ct
								from  project inner join mobarat_school on mobarat_school.school_id=project.school_id and mobarat_school.mobarat_year=project.mobarat_year 
								where mobarat_school.is_present=1 and mobarat_school.mobarat_year=myear and mobarat_school.presence_assurance=1 and project_type=ptype 
								and suite like concat(judgeDayEnable_code_no,'%')
								#and ( project_stage =(select judge_stage from person_judge where judge_id=judeid) or (select judge_stage from person_judge where judge_id=judeid)='03' )
                                and ( project_stage =jstage or jstage='03' )
								and not project_id in (select project_id from project_judge where mobarat_year=myear and  judge_personId=persID)
								order by ct asc) as t,(select @lim:=0 ) as l) as tt
								where counter<=lim;
						END LOOP;
						CLOSE cur;
						update judge_selecting set isProjectRegister=1 where person_id=persID and mobarat_year=myear and select_no like concat(judgeDayEnable_code_no_var,'%')  ;
					#end if;
				#end if;
            end if;
    end if;
END ;;
