DELIMITER ;;
CREATE PROCEDURE `RegisterOldSchoolOldOteacher`(schlID int(11),myear int(11))
BEGIN
	declare lstOteachID int(11);
    declare ID int(11);
    declare persID int(11);
    if exists(select * from mobarat_school where school_id=schlID and mobarat_year=myear) then
	set persID=(select oteacher_personid from mobarat_school  where school_id=schlID and mobarat_year=myear and mobarat_school_RegistrationStep='01');
    set lstOteachID=( select o.oteacher_id 
						from mobarat_school as m inner join person_oteacher as o on m.oteacher_id=o.oteacher_id 
							inner join person on person.Person_id =o.oteacher_personid 
							where school_id=schlID and m.oteacher_personid=persID
							order by o.mobarat_year desc  limit 1 );
    INSERT INTO person_oteacher(mobarat_year,oteacher_personid,oteacher_description,date_inserted)
		SELECT myear,OT.oteacher_personid,OT.oteacher_description,now()
		FROM person_oteacher AS OT
        WHERE OT.oteacher_id=lstOteachID;
    set ID=LAST_INSERT_ID();
    #set persID=(select oteacher_personid from person_oteacher  where oteacher_id=lstOteachID);
    update mobarat_school
		set oteacher_id=ID,oteacher_personid=persID,mobarat_school_RegistrationStep='02',date_step02=now()
        where school_id=schlID and mobarat_year=myear;
	end if;
END ;;
